/** Local generated bytes only; warm worker versus synchronous equivalent integrity + wire work. */
import { createHash } from 'node:crypto'
import { mkdtemp, writeFile, rm } from 'node:fs/promises'
import { readFileSync, statSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import assert from 'node:assert/strict'
import { OutboundEncoder } from '../src/plugins/builtin/snowluma/outbound.ts'
const dir = await mkdtemp(join(tmpdir(), 'outbound-warm-'))
const encoder = new OutboundEncoder()
let heartbeat: ReturnType<typeof setInterval> | undefined
try {
  const sources = []
  for (const mib of [0.1, 1, 10]) {
    const bytes = Buffer.alloc(Math.floor(mib * 1024 * 1024), 42)
    const path = join(dir, String(mib))
    await writeFile(path, bytes)
    sources.push({
      mib,
      index: 0,
      path,
      bytes: bytes.length,
      hash: createHash('sha256').update(bytes).digest('hex'),
    })
  }
  const envelope = () => ({ message: [{ type: 'image', data: { file: '' } }] })
  const warm = await encoder.encode(envelope(), [sources[0]!])
  warm.release()
  for (const source of sources)
    for (const mode of ['sync-integrity', 'warm-worker']) {
      let heartbeatMaxMs = 0,
        previous = performance.now()
      heartbeat = setInterval(() => {
        const now = performance.now()
        heartbeatMaxMs = Math.max(heartbeatMaxMs, now - previous - 5)
        previous = now
      }, 5)
      await new Promise((resolve) => setTimeout(resolve, 10))
      let cpuMs = 0,
        elapsedMs = 0,
        wireBytes = 0
      for (let repeat = 0; repeat < 3; repeat++) {
        const cpu = process.cpuUsage(),
          start = performance.now()
        if (mode === 'sync-integrity') {
          const before = statSync(source.path),
            bytes = readFileSync(source.path),
            after = statSync(source.path)
          assert.equal(before.size, source.bytes)
          assert.equal(after.size, before.size)
          assert.equal(after.mtimeMs, before.mtimeMs)
          assert.equal(after.ctimeMs, before.ctimeMs)
          assert.equal(createHash('sha256').update(bytes).digest('hex'), source.hash)
          const value = envelope()
          value.message[0]!.data.file = `base64://${bytes.toString('base64')}`
          wireBytes = Buffer.byteLength(JSON.stringify(value))
        } else {
          const lease = await encoder.encode(envelope(), [source])
          wireBytes = lease.bytes.byteLength
          lease.release()
        }
        elapsedMs += performance.now() - start
        const used = process.cpuUsage(cpu)
        cpuMs += (used.user + used.system) / 1000
        await new Promise((resolve) => setTimeout(resolve, 10))
      }
      clearInterval(heartbeat)
      console.log(
        JSON.stringify({
          mode,
          sourceMiB: source.mib,
          repetitions: 3,
          averageWallMs: elapsedMs / 3,
          averageCpuMs: cpuMs / 3,
          heartbeatMaxMs,
          wireBytes,
          processMaxRssMiB: process.resourceUsage().maxRSS / 1024,
        }),
      )
    }
} finally {
  clearInterval(heartbeat)
  encoder.dispose()
  await rm(dir, { recursive: true, force: true })
}
